import{R as s,e as t,f as a,U as i}from"./chunks/framework.ywem4qy5.js";const h=JSON.parse('{"title":"Statuses","description":"","frontmatter":{},"headers":[],"relativePath":"submissions/statuses.md","filePath":"submissions/statuses.md","lastUpdated":1775908585000}'),o={name:"submissions/statuses.md"};function l(n,e,r,u,p,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h1><p>Statuses are labels you can use to organize and manage submissions after they have been saved.</p><p>They are useful when “new submission” is not enough detail for your team’s workflow.</p><p>Typical examples are:</p><ul><li><code>new</code></li><li><code>in-progress</code></li><li><code>approved</code></li><li><code>closed</code></li></ul><p>This gives teams a simple workflow around submissions without changing the form itself.</p><p>Each form can choose a default status for new submissions.</p><p>That means different forms can enter your process in different states, depending on how they are handled internally.</p><p>Statuses are separate from whether a submission is:</p><ul><li>complete</li><li>incomplete</li><li>spam</li></ul><p>Those are system states. A status is your workflow label on top of that.</p><p>Statuses are managed in Formie settings.</p><p>Each status has:</p><ul><li>a name</li><li>a handle</li><li>a color</li><li>an optional description</li></ul><p>One status can be marked as the default.</p><ul><li>You cannot delete the default status while it is the default.</li><li>A status that is still in use by submissions cannot be freely removed.</li><li>Statuses are stored in project config, so they can travel with the project like other shared settings.</li></ul><p>Add statuses when a team actually needs them for review or follow-up.</p><p>If every submission is handled the same way, the default status may be all you need.</p>',18)])])}const m=s(o,[["render",l]]);export{h as __pageData,m as default};
